/// How many of [i18nKeys] are the SDK's own (sdk.*).
const int i18nSdkKeyCount = 578;

/// The supported languages, English first.
const List<String> i18nLanguages = <String>["en", "nl", "fr", "de", "es"];

/// Each language's own name, for pickers.
const Map<String, String> i18nLanguageNames = <String, String>{
  "en": "English",
  "nl": "Nederlands",
  "fr": "Français",
  "de": "Deutsch",
  "es": "Español",
};

/// One language's table (English for anything else).
Map<String, String> i18nTableOf(String lang) {
  switch (lang) {
    case "nl":
      return i18nNl;
    case "fr":
      return i18nFr;
    case "de":
      return i18nDe;
    case "es":
      return i18nEs;
    default:
      return i18nEn;
  }
}
